const isoScaleX = 0.72;
const isoScaleY = 0.39;
const roleColors: Record<Enemy['role'], string> = { assault: '#b35a4b', suppressor: '#b67850', technician: '#7d6daf', elite: '#c34f6e', boss: '#d04c46' };

function project(x: number, y: number, cx: number, cy: number, width: number, height: number) { const dx = x - cx; const dy = y - cy; return { x: width / 2 + (dx - dy) * isoScaleX, y: height / 2 + (dx + dy) * isoScaleY }; }
function screenVectorToWorld(dx: number, dy: number): Vec2 { const wx = dx / (2 * isoScaleX) + dy / (2 * isoScaleY); const wy = dy / (2 * isoScaleY) - dx / (2 * isoScaleX); const l = Math.hypot(wx, wy); return l > 0.01 ? { x: wx / l, y: wy / l } : { x: 0, y: 0 }; }
function objectiveScreenDirection(dx: number, dy: number) { const sx = (dx - dy) * isoScaleX; const sy = (dx + dy) * isoScaleY; const angle = Math.atan2(sy, sx); const octant = (Math.round(angle / (Math.PI / 4)) + 8) % 8; return ['RIGHT', 'DOWN-RIGHT', 'DOWN', 'DOWN-LEFT', 'LEFT', 'UP-LEFT', 'UP', 'UP-RIGHT'][octant]; }
function drawDiamond(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, fill: string, stroke: string) { ctx.beginPath(); ctx.moveTo(x, y - h / 2); ctx.lineTo(x + w / 2, y); ctx.lineTo(x, y + h / 2); ctx.lineTo(x - w / 2, y); ctx.closePath(); ctx.fillStyle = fill; ctx.fill(); ctx.strokeStyle = stroke; ctx.stroke(); }
function objectColor(object: CombatObject) {
  if (object.kind === 'conduit') return object.exposed ? '#77542d' : '#293d39';
  if (object.kind === 'coolant') return '#2d5360';
  if (object.kind === 'breachPlate') return '#453d37';
  if (object.kind === 'doorControl') return '#416d62';
  if (object.kind === 'gravityControl') return '#536d8c';
  if (object.kind === 'sealControl') return '#805b42';
  if (object.kind === 'powerControl') return '#654f7a';
  if (object.kind === 'salvageNode') return '#6c6b46';
  if (object.kind === 'anchorNode') return '#6f3d68';
  if (object.material === 'light') return '#3c4741';
  if (object.material === 'industrial') return '#2f3a39';
  return '#222b2a';
}

function drawObject(ctx: CanvasRenderingContext2D, object: CombatObject, camX: number, camY: number, width: number, height: number) {
  if (!object.active) return; const a = project(object.x, object.y, camX, camY, width, height); const b = project(object.x + object.w, object.y, camX, camY, width, height); const c = project(object.x + object.w, object.y + object.h, camX, camY, width, height); const d = project(object.x, object.y + object.h, camX, camY, width, height); const isPanel = object.kind === 'doorControl' || object.kind === 'gravityControl' || object.kind === 'sealControl' || object.kind === 'powerControl' || object.kind === 'salvageNode'; const topOffset = isPanel ? 12 : 24;
  ctx.fillStyle = objectColor(object); ctx.strokeStyle = object.exposed ? '#dfaa58' : '#52635f'; ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.lineTo(c.x, c.y); ctx.lineTo(d.x, d.y); ctx.closePath(); ctx.fill(); ctx.stroke(); ctx.fillStyle = isPanel ? '#162523' : '#151d1c'; ctx.beginPath(); ctx.moveTo(a.x, a.y - topOffset); ctx.lineTo(b.x, b.y - topOffset); ctx.lineTo(c.x, c.y - topOffset); ctx.lineTo(d.x, d.y - topOffset); ctx.closePath(); ctx.fill(); ctx.stroke();
  if (object.destructible && object.maxHp < 9000) { const pct = Math.max(0, object.hp / object.maxHp); const center = project(object.x + object.w / 2, object.y + object.h / 2, camX, camY, width, height); ctx.fillStyle = 'rgba(5,8,8,.8)'; ctx.fillRect(center.x - 22, center.y - topOffset - 18, 44, 3); ctx.fillStyle = object.exposed ? '#e5a34f' : '#7b9d91'; ctx.fillRect(center.x - 22, center.y - topOffset - 18, 44 * pct, 3); }
}

function renderPressureFlow(ctx: CanvasRenderingContext2D, state: SimState, camX: number, camY: number, width: number, height: number, quality: number) {
  for (const breach of state.breaches) { if (!breach.active) continue; const bp = project(breach.x, breach.y, camX, camY, width, height); ctx.strokeStyle = breach.boss ? 'rgba(239,111,78,.75)' : 'rgba(222,154,82,.7)'; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(bp.x, bp.y - 8, 26, 0, Math.PI * 2); ctx.stroke(); ctx.lineWidth = 1; const count = quality < 0.8 ? 5 : 9; for (let i = 0; i < count; i += 1) { const phase = (state.time * (160 + i * 9) + i * 83) % 360; const angle = i / count * Math.PI * 2; const distance = 90 + phase; const wx = breach.x - Math.cos(angle) * distance; const wy = breach.y - Math.sin(angle) * distance; const start = project(wx, wy, camX, camY, width, height); const end = project(wx + Math.cos(angle) * 62, wy + Math.sin(angle) * 62, camX, camY, width, height); ctx.strokeStyle = 'rgba(185,215,205,.18)'; ctx.beginPath(); ctx.moveTo(start.x, start.y); ctx.lineTo(end.x, end.y); ctx.stroke(); } }
}

function drawMobileTargetLock(ctx: CanvasRenderingContext2D, enemy: Enemy, pos: Vec2, time: number) {
  const radiusX = enemy.role === 'boss' ? 50 : 33;
  const radiusY = enemy.role === 'boss' ? 58 : 39;
  const arm = enemy.role === 'boss' ? 15 : 11;
  const left = pos.x - radiusX;
  const right = pos.x + radiusX;
  const top = pos.y - 12 - radiusY;
  const bottom = pos.y - 12 + radiusY;
  const pulse = 0.72 + Math.sin(time * 9) * 0.14;
  ctx.strokeStyle = `rgba(167,238,215,${pulse})`;
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.moveTo(left + arm, top); ctx.lineTo(left, top); ctx.lineTo(left, top + arm);
  ctx.moveTo(right - arm, top); ctx.lineTo(right, top); ctx.lineTo(right, top + arm);
  ctx.moveTo(left, bottom - arm); ctx.lineTo(left, bottom); ctx.lineTo(left + arm, bottom);
  ctx.moveTo(right - arm, bottom); ctx.lineTo(right, bottom); ctx.lineTo(right, bottom - arm);
  ctx.stroke();
  ctx.fillStyle = 'rgba(190,244,227,.86)';
  ctx.font = '800 8px ui-monospace, monospace';
  ctx.textAlign = 'center';
  ctx.fillText(enemy.role === 'boss' ? 'BOSS TRACK' : 'TRACK', pos.x, top - 7);
  ctx.textAlign = 'left';
  ctx.lineWidth = 1;
}

function drawObjectiveMarker(ctx: CanvasRenderingContext2D, state: SimState, mission: Contract, object: CombatObject, camX: number, camY: number, width: number, height: number, time: number) {
  if (!object.active) return;
  const mandatoryIds = mission.objectiveMode === 'pressure-recovery' ? ['service-seal'] : mission.objectiveMode === 'grid-isolation' ? ['grid-isolator-a', 'grid-isolator-b'] : mission.objectiveMode === 'gravity-stabilization' ? ['gravity-control-a', 'gravity-control-b'] : mission.objectiveMode === 'machinery-recovery' ? ['salvage-node-a', 'salvage-node-b'] : mission.objectiveMode === 'emergency-boarding' ? ['door-control', 'boarding-lock'] : mission.objectiveMode === 'momentum-capture' ? ['capture-drum-a', 'capture-drum-b'] : mission.objectiveMode === 'thermal-routing' ? ['purge-valve-a', 'purge-valve-b'] : ['salvage-node-a', 'salvage-node-b', 'salvage-node-c'];
  const optional = !!mission.megastructure && object.id === 'mega-optional-cache';
  if (!mandatoryIds.includes(object.id) && !optional) return;
  const reopenedSeal = object.id === 'service-seal' && state.breaches.some(breach => breach.id === 'service-breach' && breach.active);
  if (object.exposed && !reopenedSeal) return;
  const pos = project(object.x + object.w / 2, object.y + object.h / 2, camX, camY, width, height);
  const pulse = 0.72 + Math.sin(time * 6) * 0.18;
  ctx.strokeStyle = `rgba(191,221,151,${pulse})`; ctx.fillStyle = `rgba(191,221,151,${0.08 + pulse * 0.06})`; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(pos.x, pos.y - 34); ctx.lineTo(pos.x + 10, pos.y - 24); ctx.lineTo(pos.x, pos.y - 14); ctx.lineTo(pos.x - 10, pos.y - 24); ctx.closePath(); ctx.fill(); ctx.stroke();
  ctx.fillStyle = 'rgba(214,232,185,.92)'; ctx.font = '800 7px ui-monospace, monospace'; ctx.textAlign = 'center'; ctx.fillText(optional ? 'OPT' : 'OBJ', pos.x, pos.y - 39); ctx.textAlign = 'left'; ctx.lineWidth = 1;
}

