    for (const x of [360, 820, 1215, 1510, 1980]) { const a = project(x, 180, camX, camY, width, height); const b = project(x, 900, camX, camY, width, height); ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke(); }
