    for (const point of [{ x: 720, y: 500 }, { x: 1390, y: 520 }, { x: 1990, y: 520 }]) { const pos = project(point.x, point.y, camX, camY, width, height); ctx.strokeStyle = 'rgba(198,149,92,.18)'; ctx.lineWidth = 3; ctx.beginPath(); ctx.ellipse(pos.x, pos.y, 62, 31, 0, 0, Math.PI * 2); ctx.stroke(); ctx.beginPath(); ctx.ellipse(pos.x, pos.y, 31, 15, 0, 0, Math.PI * 2); ctx.stroke(); }
