function hudFrom(state: SimState): HudState { const sector = getPlayerSector(state); const p = state.player; const boss = getBoss(state); const context = getContextAction(state); const squadRemaining = getSquadRemaining(state); const classStatus = getClassMechanicStatus(state); return { classId: classStatus.id, classLabel: classStatus.label, classDetail: classStatus.detail, classActive: classStatus.active, hp: p.hp, maxHp: p.maxHp, armor: p.armor, maxArmor: p.maxArmor, capacitor: p.capacitor, maxCapacitor: p.maxCapacitor, mag: p.mags[p.currentWeapon], heat: p.weaponHeat[p.currentWeapon], weapon: p.currentWeapon, ability: [...p.abilityCooldowns] as [number, number, number], dodge: p.dodgeCooldown, reload: p.reloadT, venting: p.ventT > 0, dead: p.dead, complete: state.complete, kills: state.kills, squadRemaining, extractionReady: state.bossGateHold && squadRemaining === 0 && !state.bossActive && !state.complete, pressureState: sector.pressureState, pressure: sector.pressure, gravity: sector.gravity, eventText: state.eventText, eventT: state.eventT, contextLabel: context?.label ?? '', bossActive: state.bossActive && !!boss && !boss.dead, bossLabel: boss?.label ?? 'Deep-zone target', bossHp: boss?.hp ?? 0, bossMaxHp: boss?.maxHp ?? 1, bossArmor: boss?.armor ?? 0, bossMaxArmor: boss?.maxArmor ?? 1, bossPhase: boss?.bossPhase ?? 1, bossPattern: boss?.bossPattern ?? 'none', vacuumExposure: p.vacuumExposure, disrupted: p.disrupted, consumableCooldown: p.consumableCooldown, damageDealt: state.telemetry.damageDealt, damageTaken: state.telemetry.damageTaken, shots: { ...state.telemetry.weaponShots }, abilityUses: [...state.telemetry.abilityUses] as [number, number, number] }; }
